CREATE UNIQUE INDEX run_leases_token_idx ON run_leases (run_id, fencing_token);

CREATE INDEX runs_claim_idx ON runs (status, created_at, id);

CREATE UNIQUE INDEX runs_idempotency_idx ON runs (created_by_console_account_id, idempotency_key) WHERE (idempotency_key IS NOT NULL);

