CREATE TRIGGER scenario_versions_immutable BEFORE UPDATE ON scenario_versions WHEN OLD.definition IS NOT NEW.definition OR OLD.version_no IS NOT NEW.version_no OR OLD.scenario_id IS NOT NEW.scenario_id OR OLD.kind IS NOT NEW.kind OR OLD.compiler_version IS NOT NEW.compiler_version OR OLD.source_digest IS NOT NEW.source_digest BEGIN SELECT RAISE(ABORT, 'scenario_versions immutable'); END;

CREATE TRIGGER runs_snapshot_immutable BEFORE UPDATE ON runs WHEN OLD.snapshot IS NOT NEW.snapshot OR OLD.snapshot_digest IS NOT NEW.snapshot_digest OR OLD.target_id IS NOT NEW.target_id OR OLD.scenario_id IS NOT NEW.scenario_id OR OLD.scenario_version_id IS NOT NEW.scenario_version_id BEGIN SELECT RAISE(ABORT, 'runs immutable'); END;

CREATE TRIGGER attempts_closed_immutable BEFORE UPDATE ON attempts WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELLED') AND (OLD.status IS NOT NEW.status OR OLD.output IS NOT NEW.output OR OLD.error IS NOT NEW.error OR OLD.finished_at IS NOT NEW.finished_at) BEGIN SELECT RAISE(ABORT, 'attempts immutable'); END;
